import json

def rows_to_map(obj):
    rows=((obj.get("response",{}).get("data",{}) or {}).get("rows") or [])
    out={}
    for r in rows:
        k=(r.get("keys") or [None])[0]
        if k: out[k]={"clicks":r.get("clicks",0),"impressions":r.get("impressions",0),"ctr":r.get("ctr",0),"position":r.get("position")}
    return out

